adial-gradient(circle at 80% 70%, rgba(168, 85, 247, 0.08) 0%, transparent 50%);\n  filter: blur(60px);\n}\n\n.start-content {\n  position: relative;\n  z-index: 10;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: clamp(18px, 4vw, 28px);\n  width: min(88vw, 620px);\n  padding: 34px 18px 58px;\n}\n\n.game-title {\n  margin: 0;\n  text-align: center;\n  cursor: default;\n  font-family: Orbitron, system-ui, sans-serif;\n}\n\n.title-main,\n.title-sub {\n  display: block;\n}\n\n.title-main {\n  color: #fff;\n  font-size: clamp(38px, 8vw, 68px);\n  font-weight: 900;\n  letter-spacing: 0.18em;\n  text-shadow:\n    0 0 10px #00e5ff,\n    0 0 20px #00e5ff,\n    0 0 40px #006e80;\n  animation: neon-pulse 2s ease-in-out infinite alternate;\n}\n\n.title-sub {\n  margin-top: 8px;\n  color: #c084fc;\n  font-size: clamp(13px, 2.5vw, 19px);\n  letter-spacing: 0.52em;\n  text-shadow: 0 0 10px #a855f7;\n  text-transform: uppercase;\n}\n\n.start-divider {\n  display: flex;\n  align-items: center;\n  gap: 20px;\n  width: min(100%, 400px);\n}\n\n.line {\n  flex: 1;\n  height: 1px;\n  background: linear-gradient(90deg, transparent, #2a2a50, transparent);\n}\n\n.diamond {\n  width: 6px;\n  height: 6px;\n  background: #00e5ff;\n  box-shadow: 0 0 10px #00e5ff;\n  transform: rotate(45deg);\n}\n\n.start-menu {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n  width: min(280px, 100%);\n}\n\n.start-btn {\n  position: relative;\n  min-height: 50px;\n  padding: 14px 18px;\n  overflow: hidden;\n  border: 0;\n  background: transparent;\n  color: #e8e4f0;\n  cursor: pointer;\n  font-family: Orbitron, system-ui, sans-serif;\n  font-size: 16px;\n  font-weight: 700;\n  letter-spacing: 0.18em;\n  transition: opacity 0.3s, transform 0.3s;\n}\n\n.start-btn:disabled {\n  cursor: not-allowed;\n}\n\n.start-btn:not(:disabled):hover {\n  transform: translateY(-1px);\n}\n\n.start-btn--compact {\n  min-height: 44px;\n  color: #a09cb8;\n  font-size: 13px;\n  letter-spacing: 0.14em;\n}\n\n.start-btn--compact:not(:disabled):hover {\n  color: #00e5ff;\n}\n\n.start-btn--compact .btn-border {\n  border-color: #5c5878;\n}\n\n.start-btn--compact:not(:disabled):hover .btn-border {\n  border-color: #00e5ff;\n  background: rgba(0, 229, 255, 0.07);\n}\n\n.btn-text,\n.placeholder-tag,\n.btn-accent {\n  position: relative;\n  z-index: 1;\n}\n\n.btn-border {\n  position: absolute;\n  inset: 0;\n  border: 1px solid #2a2a50;\n  clip-path: polygon(10% 0, 100% 0, 100% 70%, 90% 100%, 0 100%, 0 30%);\n  transition: background 0.3s, box-shadow 0.3s, border-color 0.3s;\n}\n\n.primary .btn-border {\n  border-color: #00e5ff;\n  background: rgba(0, 229, 255, 0.03);\n}\n\n.primary:not(:disabled):hover .btn-border {\n  background: rgba(0, 229, 255, 0.1);\n  box-shadow: inset 0 0 20px rgba(0, 229, 255, 0.2);\n}\n\n.primary .btn-accent {\n  position: absolute;\n  top: 0;\n  right: 20px;\n  width: 40px;\n  height: 2px;\n  background: #00e5ff;\n  box-shadow: 0 0 10px #00e5ff;\n}\n\n.secondary {\n  opacity: 0.6;\n}\n\n.secondary .btn-border {\n  border-color: #5c5878;\n}\n\n.placeholder-tag {\n  position: absolute;\n  top: 50%;\n  right: 15px;\n  padding: 2px 4px;\n  border: 1px solid #5c5878;\n  color: #5c5878;\n  font-size: 8px;\n  letter-spacing: 0.08em;\n  transform: translateY(-50%);\n}\n\n.placeholder-tag--found {\n  border-color: #2ed573;\n  color: #2ed573;\n}\n\n.start-footer {\n  position: absolute;\n  bottom: 22px;\n  text-align: center;\n  font-family: 'JetBrains Mono', monospace;\n  color: #5c5878;\n}\n\n.footer-line {\n  margin-bottom: 5px;\n  font-size: 11px;\n  letter-spacing: 0.1em;\n}\n\n.footer-copyright {\n  font-size: 9px;\n  opacity: 0.5;\n}\n\n@keyframes grid-scroll {\n  from {\n    background-position: 0 0;\n  }\n\n  to {\n    background-position: 0 500px;\n  }\n}\n\n@keyframes neon-pulse {\n  from {\n    opacity: 0.9;\n    text-shadow: 0 0 10px #00e5ff, 0 0 20px #00e5ff, 0 0 40px #006e80;\n  }\n\n  to {\n    opacity: 1;\n    text-shadow: 0 0 15px #00e5ff, 0 0 30px #00e5ff, 0 0 60px #00f0ff, 0 0 10px #fff;\n  }\n}\n\n@media (max-width: 720px) {\n  .start-screen {\n    min-height: 500px;\n  }\n\n  .start-content {\n    width: 100%;\n    padding: 32px 16px 72px;\n  }\n\n  .title-main {\n    letter-spacing: 0.12em;\n  }\n\n  .title-sub {\n    letter-spacing: 0.36em;\n  }\n\n  .start-btn {\n    font-size: 15px;\n  }\n}\n"],"sourceRoot":""}]);
